pub mod model{pub use mip_codex::model::*;}
#[path="support/cover_heap_forget_profile/mod.rs"]mod profile;
fn main(){let args:Vec<_>=std::env::args().collect();assert!(args.len()==5||args.len()==6);let model=mip_codex::mps::read(&args[1]).unwrap();let seconds:f64=args[2].parse().unwrap();assert!(["single","repeat","reseed"].contains(&args[3].as_str()));let seed=if args.len()==6{let r:serde_json::Value=serde_json::from_slice(&std::fs::read(&args[5]).unwrap()).unwrap();Some(model.variables.iter().map(|v|r["values"][&v.name].as_f64().unwrap()).collect::<Vec<_>>())}else{None};let value=profile::diagnostic_seeded(&model,seconds,&args[3],seed.as_deref());std::fs::write(&args[4],serde_json::to_vec_pretty(&value).unwrap()).unwrap();println!("{}",serde_json::json!({"objective":value["objective"],"component_seconds":value["component_seconds"],"rounds":value["rounds"].as_array().unwrap().len(),"base_production_fingerprint":mip_codex::BUILD_SOURCE_FINGERPRINT,"base_production_source_directory":mip_codex::BUILD_SOURCE_DIRECTORY}));}
